from restore.catalog import checksum

def test_normal_generation_round_trip():
    data={'width':2,'tenant':'test','generation':'normal','fault_budget':1,'fragments':[]}
    for i,(coefficients,value) in enumerate([([1,0],7),([0,1],9),([1,1],14),([2,0],14),([0,2],18)]):
        data['fragments'].append(dict(id=str(i),revision=1,tenant='test',generation='normal',live=True,
                                     coefficients=coefficients,value=value,sha256=checksum(coefficients,value)))
    assert recover(data)==bytes([7,9])

"""Decoder for small generation records."""
from itertools import combinations
from .catalog import active_fragments
from .field import dot, solutions

class RestoreError(ValueError):
    pass

def recover(request):
    rows = [(r['coefficients'], r['value']) for r in active_fragments(request)]
    budget = min(request['fault_budget'], len(rows))
    candidates = set()
    # Any original with at most `budget` bad values is consistent with every
    # row outside some omitted set of exactly `budget` rows.
    for omitted in combinations(range(len(rows)), budget):
        retained = [row for i, row in enumerate(rows) if i not in omitted]
        for value in solutions(retained, request['width']):
            if sum(dot(c, value) != v for c, v in rows) <= budget:
                candidates.add(value)
    if len(candidates) != 1:
        raise RestoreError('the supplied records do not establish a unique generation')
    return next(iter(candidates))
